package com.az.scicalc;
import org.junit.Test;import static org.junit.Assert.*;
public class KeyParityTest {
 final MathEngine engine=new MathEngine();
 Formula fields(String kind,String name,String...values){Formula f=new Formula();f.template(kind,name);Formula.Node node=f.root.nodes.get(0);for(int i=0;i<values.length;i++){node.rows.get(i).nodes.clear();if(!values[i].isEmpty())node.rows.get(i).add(new Formula.Node("text",values[i]));}return f;}
 @Test public void mixedRecurringAndDms(){assertEquals("7/3",engine.evaluate(fields("mixed","","2","1","3").source(1),false));assertEquals("-7/3",engine.evaluate(fields("mixed","","-2","1","3").source(1),false));assertEquals("1/3",engine.evaluate(fields("recurring","","0","","3").source(1),false));assertEquals("611/495",engine.evaluate(fields("recurring","","1","2","34").source(1),false));assertEquals(30.5,engine.value(fields("dms","","30","30","0").source(1)),1e-12);}
 @Test public void degreeRadianGradian(){Formula f=fields("func","Cot","45");assertEquals(1,engine.value(f.source(0)),1e-12);f=fields("func","Cot","50");assertEquals(1,engine.value(f.source(2)),1e-12);f=fields("func","ArcCot","1");assertEquals(45,engine.value(f.source(0)),1e-12);assertEquals(50,engine.value(f.source(2)),1e-12);assertEquals(Math.PI/4,engine.value(f.source(1)),1e-12);}
 @Test public void rootsProductLogAndNumericIntegration(){assertEquals("2",engine.evaluate(fields("nthroot","","5","32").source(1),false));assertEquals("120",engine.evaluate(fields("product","","x","1","5","x").source(1),false));Formula f=new Formula();f.call("LogBase",2);Formula.Node n=f.root.nodes.get(0);n.rows.get(0).add(new Formula.Node("text","2"));n.rows.get(1).add(new Formula.Node("text","8"));assertEquals("3",engine.evaluate(f.source(1),false));for(String method:new String[]{"LegendreGauss","Romberg","GaussKronrod"})assertEquals(1.0/3,engine.value(engine.evaluate(fields("integral",method,"x^2","0","1","x").source(1),false)),1e-8);}
 @Test public void percentModesAndComposition(){assertEquals(120,engine.value(MathFunctions.percent("100+20%",true)),1e-12);assertEquals(100.2,engine.value(MathFunctions.percent("100+20%",false)),1e-12);assertEquals(20,engine.value(MathFunctions.percent("200*10%",true)),1e-12);assertEquals(132,engine.value(MathFunctions.percent("100+20%+10%",true)),1e-12);assertEquals(240,engine.value(MathFunctions.percent("(100+20%)*2",true)),1e-12);}
 @Test public void structuredPasteAndMatrixNavigation(){Formula f=new Formula();f.insertExpression("{{1,2},{3,4}}");assertEquals("matrix",f.root.nodes.get(0).kind);assertEquals("-2",engine.evaluate("Det("+f.source(1)+")",false));String tree=f.save();Formula g=new Formula();g.insertSaved(tree);assertEquals(f.source(1),g.source(1));g.clear();g.grid(2,2,false);Formula.Node matrix=g.root.nodes.get(0);g.text("1");g.vertical(true);assertSame(matrix.rows.get(2),g.cursor);g.text("3");g.right();g.text("4");g.vertical(false);g.text("2");assertTrue(g.complete());}
 @Test public void weightedStatisticsAndRegressions(){StatsData d=new StatsData(new double[]{1,2,4},new double[]{0,0,0},new double[]{1,2,1});assertEquals(4,d.n,0);assertEquals(2.25,d.mean(),0);assertEquals(1.1875,d.populationVariance(),1e-12);assertEquals(19.0/12,d.sampleVariance(),1e-12);assertEquals(2,d.median(),0);d=new StatsData(new double[]{1,2,3},new double[]{3,5,7},new double[]{1,3,2});assertArrayEquals(new double[]{1,2,1},d.regression("linear"),1e-9);d=new StatsData(new double[]{0,1,2,3},new double[]{1,6,17,34},new double[]{1,1,1,1});double[] r=d.regression("quadratic");assertEquals(1,r[0],1e-9);assertEquals(2,r[1],1e-9);assertEquals(3,r[2],1e-9);}
 @Test public void signed64BitAndFormat(){assertEquals(255,BaseExpression.evaluate("FF",16));assertEquals(-1,BaseExpression.evaluate("FFFFFFFFFFFFFFFF",16));assertEquals(-2,BaseExpression.evaluate("not 1",10));assertEquals(3,BaseExpression.evaluate("(12 >> 2) and 7",10));assertEquals(9,BaseExpression.evaluate("5 xor 12",10));assertEquals(Long.MIN_VALUE,BaseExpression.evaluate("9223372036854775807+1",10));assertEquals("3.3 k",ResultFormat.format("3300","si",10));assertEquals("MCMXCIV",ResultFormat.roman(1994));assertEquals("MMMCMXCIX",ResultFormat.roman(3999));}
 @Test public void distributionsAndFactorization(){assertEquals(.682689492137,engine.value(MathFunctions.call("normalcdf",new String[]{"-1","1","0","1"})),1e-9);assertEquals(.5,engine.value(MathFunctions.call("tcdf",new String[]{"-Infinity","0","10"})),1e-9);assertEquals("2^2*3",MathFunctions.factorDisplay(engine.evaluate("FactorInteger(12)",false)));}
 @Test public void implicitProductsAndScopedVariables(){Formula f=new Formula();f.text("2");f.variable("x");f.template("func","Sin");f.text("30");assertEquals("2*x*Sin((30)*Pi/180)",f.source(0));java.util.Map<String,String> values=java.util.Map.of("x","3","a","2");String s=ScopedValues.apply("x+Integrate(a*x,{x,0,1})+D(x^2,x)",values);assertEquals("4+2*x",engine.evaluate(s,false));assertTrue(s.contains("{x,0,1}"));assertEquals("(3)+Sum(x,{x,1,3})",ScopedValues.apply("x+Sum(x,{x,1,3})",values));assertEquals(4,engine.value(ScopedValues.apply("D(x^2,x)/.x->(2)",values)),1e-12);assertEquals("True",engine.evaluate(MathFunctions.comparison("2=2"),false));assertEquals("False",engine.evaluate(MathFunctions.comparison("2!=2"),false));assertEquals("x:=2",MathFunctions.comparison("x:=2"));}
 @Test public void existingOperandTemplatesAndPlot(){Formula f=new Formula();f.text("2");f.template("mixed","");f.text("1");f.right();f.text("3");assertEquals("7/3",engine.evaluate(f.source(1),false));f.clear();f.text("30");f.template("dms","");f.text("30");assertEquals(30.5,engine.value(f.source(1)),1e-12);assertEquals(-30.5,engine.value(fields("dms","","-30","30","0").source(1)),1e-12);f.clear();f.text("5");f.template("nthroot","");f.text("32");assertEquals("2",engine.evaluate(f.source(1),false));assertEquals("-1/3",ResultFormat.mixed("-1","3"));assertEquals("-2 1/3",ResultFormat.mixed("-7","3"));assertEquals(1,new NumericExpression("Cot(x)").value(Math.PI/4),1e-12);assertEquals(-2,new NumericExpression("Surd(x,3)").value(-8),1e-12);assertEquals(5,engine.value("EuclideanDistance({0,0},{3,4})"),1e-12);}
 @Test public void exportsAndTypedAnswers() throws Exception{Formula f=new Formula();f.text("1");f.template("frac","");f.text("2");assertEquals("\\frac{1}{2}",MathExport.latex(f));assertTrue(MathExport.mathml(f).contains("<mfrac>"));javax.xml.parsers.DocumentBuilderFactory.newInstance().newDocumentBuilder().parse(new java.io.ByteArrayInputStream(MathExport.mathml(f).getBytes(java.nio.charset.StandardCharsets.UTF_8)));f.clear();f.insertExpression("{{1,2},{3,4}}");assertEquals("\\begin{bmatrix}1 & 2\\\\3 & 4\\end{bmatrix}",MathExport.latex(f));assertEquals("True",engine.evaluate("MatrixQ({{1/2,0},{0,1/3}},NumericQ)",false));assertEquals("True",engine.evaluate("VectorQ({1,2,3},NumericQ)",false));}
}
